def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    strong_prev_bids = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('hp', 0) > 0 and opp.get('budget', 0) > 0:
                    strong_prev_bids.append(float(bid))

    if not alive_opponents:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    strongest_prev = max(strong_prev_bids) if strong_prev_bids else highest_prev

    alive_count = len(alive_opponents) + 1
    expected_units = supply / float(WATER_REQ)
    scarcity = alive_count - expected_units

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1

    if no_water_days >= 2:
        danger += 3
    elif no_water_days >= 1:
        danger += 1

    if scarcity >= 3:
        danger += 3
    elif scarcity >= 2:
        danger += 2
    elif scarcity >= 1:
        danger += 1

    if supply <= 16:
        danger += 2
    elif supply <= 18:
        danger += 1
    elif supply >= 23:
        danger -= 1

    if day >= 8:
        danger += 1

    if hp <= 2 or no_water_days >= 2:
        emergency = max(strongest_prev + 8.0, 135.0)
        return float(min(budget, emergency))

    if danger <= 0:
        bid = 28.0 if supply >= 23 else 36.0
    elif danger == 1:
        bid = max(52.0, strongest_prev * 0.58)
    elif danger == 2:
        bid = max(74.0, strongest_prev * 0.72)
    elif danger == 3:
        bid = max(92.0, strongest_prev + 2.5)
    elif danger == 4:
        bid = max(108.0, strongest_prev + 4.0)
    else:
        bid = max(122.0, strongest_prev + 6.0)

    if supply >= 24 and hp >= 7 and no_water_days == 0:
        bid *= 0.82
    elif supply >= 22 and danger <= 2:
        bid *= 0.9

    if budget < bid:
        if danger >= 4:
            return float(budget)
        bid = max(0.0, budget * 0.92)

    return float(min(budget, round(bid, 2)))

