def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']
    alive_opponents = {k: v for k, v in opponents_status.items() if v['alive']}
    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)
    # Gather previous bids of opponents
    prev_bids = []
    for opp in alive_opponents.values():
        trace = opp.get('previous_trace', {})
        bid = trace.get('bid')
        if bid is not None:
            prev_bids.append(bid)
    # Determine base bid
    if prev_bids:
        highest_prev = max(prev_bids)
        # If someone bid very high, we must compete
        if highest_prev >= DAILY_SALARY * 0.85:
            if hp <= 2:
                return min(budget, highest_prev + 5)
            elif hp <= 5:
                return min(budget, DAILY_SALARY * 0.6)
            else:
                return min(budget, DAILY_SALARY * 0.4)
        else:
            # Otherwise, slightly above highest previous
            target = max(DAILY_SALARY * 0.5, highest_prev + 1.5)
            if hp <= 3:
                target = max(target, DAILY_SALARY * 0.7)
            return min(budget, target)
    else:
        # No previous trace, use HP-based fallback
        if hp <= 2:
            return min(budget, DAILY_SALARY * 0.9)
        elif hp <= 5:
            return min(budget, DAILY_SALARY * 0.65)
        else:
            return min(budget, DAILY_SALARY * 0.5)
